from itertools import product
from math import gcd

# Exact bounded check; universal conclusion is supplied by the accompanying algebraic proof.
def parts_in_box(r,q):
    out=[]
    def rec(prev,k,a):
        if k==r:
            out.append(tuple(a)); return
        for x in range(min(prev,q),-1,-1): rec(x,k+1,a+[x])
    rec(q,0,[])
    return out

def conj(p,q):
    return tuple(sum(x>=c for x in p) for c in range(1,q+1))
def wt(p): return sum(p)
def contains(a,b): return all(x>=y for x,y in zip(a,b))
def bigras(n,r,s,t): return 1<=t<=r and t<=s and r<=n and s<=n and t>r+s-n

checked=0
for n in range(2,11):
  for r in range(1,n):
    q=n-r
    for s in range(1,n+1):
      for t in range(1,min(r,s)+1):
        if not bigras(n,r,s,t): continue
        tv=q-s+t
        assert bigras(n,q,n-s,tv)
        i,j=s-t+1,r-t+1
        iv,jv=(n-s)-tv+1,q-tv+1
        assert (iv,jv)==(j,i)
        B=parts_in_box(r,q); C=parts_in_box(q,r)
        image={conj(x,q) for x in B}
        assert image==set(C)
        assert all(wt(x)==wt(conj(x,q)) for x in B)
        # Ideal intervals: lambda contains i^j iff transpose contains j^i.
        core=tuple([i]*j+[0]*(r-j)); corev=tuple([j]*i+[0]*(q-i))
        J=[x for x in B if contains(x,core)]
        Jv=[x for x in C if contains(x,corev)]
        assert {conj(x,q) for x in J}==set(Jv)
        for d in range(r*q+1):
            assert sum(wt(x)==d for x in J)==sum(wt(x)==d for x in Jv)
        checked+=1
print('INPUT n=2..10; all bigrassmannian (n,r,s,t) tuples')
print('CHECKED tuples=%d' % checked)
print('VERIFIED transpose preserves weight, box quotient bases, ideal intervals, and degreewise ideal ranks')
print('RESULT PASS')
